const revokeProductAccessByGrant = `-- name: RevokeProductAccessByGrant :execrows
UPDATE billing.product_access pa SET
    revoked_at = CASE WHEN pa.starts_at <= $1::timestamptz THEN $1::timestamptz END,
    revoke_reason = CASE WHEN pa.starts_at <= $1::timestamptz THEN $2::text END,
    deleted_at = CASE WHEN pa.starts_at > $1::timestamptz THEN $1::timestamptz END,
    updated_at = $1::timestamptz
WHERE pa.merchant_id = $3::uuid AND pa.grant_id = $4::uuid
  AND pa.revoked_at IS NULL AND pa.deleted_at IS NULL
`

type RevokeProductAccessByGrantParams struct {
	RevokedAt    time.Time
	RevokeReason string
	MerchantID   uuid.UUID
	GrantID      uuid.UUID
}

// A terminated grant retracts its window: started windows are revoked, a
// window that has not started is removed.
func (q *Queries) RevokeProductAccessByGrant(ctx context.Context, arg RevokeProductAccessByGrantParams) (int64, error) {
	result, err := q.db.Exec(ctx, revokeProductAccessByGrant,
		arg.RevokedAt,
		arg.RevokeReason,
		arg.MerchantID,
		arg.GrantID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

